shaders.shader:
vec4 effect(vec2 uv) {
  float t = uSongTime;
  vec2 p = (uv - .5) * vec2(uResolution.x / max(uResolution.y, 1.), 1.);
  float music = clamp(uAmplitude * .12 + uBands.x * .08, 0., .12);
  float beams = exp(-pow((p.x + .48 + .09 * sin(t * .055)) / (.16 + uv.y * .18), 2.))
              + .7 * exp(-pow((p.x - .55 + .07 * cos(t * .047)) / (.15 + uv.y * .15), 2.));
  vec3 light = vec3(.84, .36, .075) * beams * (.055 + music * .08);
  float alpha = beams * .045;
  for (int i = 0; i < 18; i++) {
    float f = float(i) + 1.;
    vec2 center = vec2((hash(f * 7.) - .5) * 2.6, hash(f * 13.) - .5);
    center += vec2(sin(t * .045 + f) * .035, sin(t * .035 + f * 2.) * .055);
    float radius = .012 + hash(f * 23.) * .035;
    float d = length(p - center);
    float mote = exp(-d * d / (radius * radius)) * (.055 + .035 * sin(t * .22 + f));
    light += mix(vec3(.45, .17, .035), vec3(1., .72, .30), hash(f * 31.)) * mote;
    alpha += mote * .6;
  }
  float quietCenter = 1. - .65 * exp(-dot(p * vec2(1.4, 1.8), p * vec2(1.4, 1.8)) * 5.);
  light *= quietCenter * 2.4;
  alpha = clamp(alpha * quietCenter * 2.4, 0., .5);
  return vec4(light / max(alpha, .001), alpha);
}

vec4 effect(vec2 uv) {
  float t = uSongTime;
  vec2 p = (uv - .5) * vec2(uResolution.x / max(uResolution.y, 1.), 1.);
  vec3 light = vec3(0.);
  float alpha = 0.;
  for (int i = 0; i < 5; i++) {
    float f = float(i);
    float center = -.26 + f * .105 + sin(p.x * (1.4 + f * .12) + t * .11 + f * .9) * .075;
    float d = abs(p.y - center);
    float glow = exp(-d * (50. + f * 4.)) * (.07 + clamp(uBands.y, 0., 1.) * .025);
    vec3 ink = mix(vec3(.12, .30, .58), vec3(.95, .54, .16), .5 + .5 * sin(f * .9 + t * .035));
    float edge = .3 + .7 * smoothstep(.18, .85, abs(p.x));
    glow *= edge;
    light += ink * glow;
    alpha += glow * .65;
  }
  float halo = exp(-dot(p - vec2(.58, .20), p - vec2(.58, .20)) * 12.) * .025;
  light += vec3(.9, .48, .15) * halo;
  light *= 2.4;
  alpha = clamp((alpha + halo) * 2.4, 0., .48);
  return vec4(light / max(alpha, .001), alpha);
}

vec4 effect(vec2 uv) {
  float t = uSongTime;
  vec2 p = (uv - .5) * vec2(uResolution.x / max(uResolution.y, 1.), 1.);
  vec3 light = vec3(0.);
  float alpha = 0.;
  for (int i = 0; i < 6; i++) {
    float f = float(i);
    float phase = fract(t * .019 + f / 6.);
    float envelope = pow(sin(PI * phase), 2.);
    vec2 center = vec2(mix(-.58, .58, mod(f, 2.)), .06 * sin(f + t * .04));
    vec2 q = (p - center) * vec2(1., 1.35);
    float radius = .07 + phase * .65 + clamp(uBands.x, 0., 1.) * .008;
    float ring = exp(-abs(length(q) - radius) * 105.) * envelope * .16;
    float soft = exp(-abs(length(q) - radius) * 24.) * envelope * .025;
    vec3 ink = mix(vec3(.10, .25, .48), vec3(.95, .61, .24), mod(f, 2.));
    light += ink * (ring + soft);
    alpha += (ring + soft) * .75;
  }
  light *= 1.8;
  alpha = clamp(alpha * 1.8, 0., .5);
  return vec4(light / max(alpha, .001), alpha);
}

vec4 effect(vec2 uv) {
  float t = uSongTime;
  vec2 p = (uv - .5) * vec2(uResolution.x / max(uResolution.y, 1.), 1.);
  float moon = exp(-dot(p - vec2(-.62, .28), p - vec2(-.62, .28)) * 17.) * .045;
  vec3 light = vec3(.15, .29, .53) * moon;
  float alpha = moon;
  for (int i = 0; i < 28; i++) {
    float f = float(i) + 1.;
    vec2 center = vec2((hash(f * 17.) - .5) * 2.9, hash(f * 37.) - .5);
    center += vec2(.012 * sin(t * .04 + f), .018 * cos(t * .035 + f));
    vec2 q = p - center;
    float radius = .003 + hash(f * 43.) * .004;
    float star = exp(-dot(q, q) / (radius * radius));
    float shimmer = .055 + .035 * sin(t * (.18 + hash(f) * .09) + f);
    float haze = exp(-dot(q, q) / .0008) * .012;
    float glow = star * shimmer + haze;
    vec3 ink = mix(vec3(.26, .43, .70), vec3(.96, .67, .30), hash(f * 61.));
    light += ink * glow;
    alpha += glow * .8;
  }
  light *= 2.2;
  alpha = clamp(alpha * 2.2, 0., .45);
  return vec4(light / max(alpha, .001), alpha);
}
